    fn tokenToSymbol(_: *BaseParser, token: Token) u16 {
        return switch (token.cat) {
            .@"eof" => 1,
            .@"newline" => 8,
            .@"ident" => 11,
            .@"integer" => 12,
            .@"minus" => 10,
            .@"lparen" => 13,
            .@"rparen" => 14,
            .@"plus" => 24,
            .@"star" => 25,
            .@"slash" => 26,
            .@"power" => 27,
